Web Application.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Web Application container

Container_Boundary(web_application, "Web Application") {
    Component(Persona-based UI Composition Engine, "Persona-based UI Composition Engine", "React / TypeScript SPA", "Renders high-performance dynamic interfaces for patients, clinicians, staff, billing officers, and auditors.")
    Component(EMR Rendering Module, "EMR Rendering Module", "React / TypeScript SPA", "Handles high-performance EMR rendering ensuring sub-second P95 load times.")
    Component(Session and Auth Handler, "Session and Auth Handler", "TypeScript", "Manages secure session handling using HttpOnly, SameSite=Strict cookies without client-side token exposure.")
}

Rel(Persona-based UI Composition Engine, Session and Auth Handler, "Uses for authentication state and secure session management")
Rel(EMR Rendering Module, Persona-based UI Composition Engine, "Feeds rendered clinical workflows into the main UI")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Edge_Ingress_Router, "Edge Ingress Router", "Envoy Proxy", "Handles edge ingress and routes incoming client requests from the Web Application.")
    Component(WAF_Protection_Module, "WAF Protection Module", "Envoy Proxy WAF Module", "Provides security filtering and web application firewall protection for low latency and security.")
    Component(Local_JWT_Validation_Module, "Local JWT Validation Module", "Envoy Proxy / HashiCorp Vault", "Validates local JWT tokens using public keys distributed by HashiCorp Vault.")
}

Rel(Edge_Ingress_Router, WAF_Protection_Module, "Inspects requests")
Rel(WAF_Protection_Module, Local_JWT_Validation_Module, "Authenticates requests")
@enduml

Scheduling Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Scheduling Service container

Container_Boundary(scheduling_service, "Scheduling Service") {
    Component(API_Controller, "API Controller", "Go HTTP Server", "Handles incoming REST requests over HTTPS from the API Gateway.")
    Component(Clash_Service, "Clash Service", "Go Business Logic", "Executes sub-millisecond clash evaluation to prevent appointment race conditions and double-bookings.")
    Component(Broker_Client, "Broker Client", "Go AMQP Client", "Publishes audit and domain events asynchronously to RabbitMQ.")
}

Rel(API_Controller, Clash_Service, "Delegates appointment booking and clash evaluation", "")
Rel(Clash_Service, Broker_Client, "Triggers domain events upon scheduling actions", "")

@enduml

Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Redis container

System_Ext(Scheduling_Service, "Scheduling Service", "External service that interacts with the cache.")
System_Ext(PostgreSQL_Database, "PostgreSQL Database", "Persistent storage for caching misses.")

Container_Boundary(Redis, "Redis") {
    Component(In_Memory_Data_Store_Component, "In-Memory Data Store Component", "Redis Enterprise / OSS (Redis Protocol)", "Manages ephemeral caching for high-performance appointment booking and resource locks.")
    Component(TLS_Termination_Encryption_Proxy_Component, "TLS Termination & Encryption Proxy Component", "Redis Stunnel / Envoy sidecar", "Enforces mTLS and AES-256 encryption in transit.")
}

Rel(Scheduling_Service, In_Memory_Data_Store_Component, "Checks and acquires resource locks", "Redis Protocol over TLS, TCP 6379")
Rel(In_Memory_Data_Store_Component, PostgreSQL_Database, "Cache-aside fallback for persistent scheduling misses", "SQL/TCP")
@enduml

RabbitMQ.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(rabbitmq, "RabbitMQ") {
    Component(Exchange_Router, "Exchange Router", "RabbitMQ Exchange", "Routes published events from microservices to the appropriate downstream queues.")
    Component(Quorum_Queues, "Quorum Queues", "RabbitMQ Quorum Queue", "Provides reliable at-least-once messaging for asynchronous event-driven integration.")
    Component(Dead_Letter_Exchange, "Dead Letter Exchange", "RabbitMQ DLX", "Receives and forwards failed messages upon consumer rejection for audit and review.")
}

Rel(Exchange_Router, Quorum_Queues, "Routes messages", "AMQP")
Rel(Quorum_Queues, Dead_Letter_Exchange, "Forwards failed messages on consumer rejection", "AMQP")

@enduml
